#include <iostream>

// Global variable
int x = 1;

void useLocal() {
    int x = 25;
    std::cout << "local x is " << x << " on entering useLocal\n";
    ++x;
    std::cout << "local x is " << x << " on exiting useLocal\n";
}

void useStaticLocal() {
    static int x = 50;
    std::cout << "local static x is " << x << " on entering useStaticLocal\n";
    ++x;
    std::cout << "local static x is " << x << " on exiting useStaticLocal\n";
}

void useGlobal() {
    std::cout << "global x is " << x << " on entering useGlobal\n";
    x *= 10;
    std::cout << "global x is " << x << " on exiting useGlobal\n";
}

int main() {
    std::cout << "global x in main is " << x << "\n";
    int x = 5;
    std::cout << "local x in main's outer scope is " << x << "\n";

    {
        int x = 7;
        std::cout << "local x in main's inner scope is " << x << "\n";
    }

    std::cout << "local x in main's outer scope is " << x << "\n";

    useLocal();
    useStaticLocal();
    useGlobal();
    useLocal();
    useStaticLocal();
    useGlobal();

    std::cout << "\nlocal x in main is " << x << "\n";
    return 0;
}

#include <iostream>

// Demonstrates call stack progression and variable lifetime
int square(int x) {
    std::cout << "Inside square: x = " << x << " (allocated on square's stack frame)\n";
    return x * x;
}

int main() {
    int a = 10; // local automatic variable on main's stack frame
    std::cout << "In main before square: a = " << a << "\n";

    int result = square(a);

    std::cout << "In main after square: " << a << " squared is " << result << "\n";
    return 0;
}
